/**
 * A simple model of a hunter. 
 * Hunters hunt all of the species in the simulation.
 * @version 2022.03.02
 */
public class Hunter extends Organism implements Actor
{
    private static final Random rand = Randomizer.getRandom();
    // A hunter hunts every species. 
    private static final Set<Class<? extends Organism>> DIET = new HashSet<>(Arrays.asList(
            Deer.class,
            Mouse.class,
            Wolf.class,
            Coyote.class,
            Eagle.class
    ));


    /**
     * Creates a new hunter.
     * @param field The field currently occupied.
     * @param location  The location within the field.
     */
    public Hunter(Field field, Location location)
    {
        super(field, location);
    }

    @Override
    protected int getFoodValue()
    {
        return 0;
    }

    /**
     * Makes the hunter hunt for nearby animals. 
     * @param environment The environment that the hunter resides in. 
     * @param newActors A list to receive new actors. 
     */
    public void act(List<Actor> newActors, Environment environment)
    {
        if(isAlive()) {
            Location newLocation = findPrey();
            if(newLocation == null) {
                // No animals found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            List<Location> adjacentGrassSpots = getField().adjacentLocationsWithSpecies(getLocation(), Grass.class);

            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else if (adjacentGrassSpots.size() > 0) {
                getField().clear(getLocation());
                setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
            }

        }
    }

    /**
     * Look for animals adjacent to the current location.
     * Only the first live animal is killed.
     * @return Location Where an animal was found, or null if it wasn't.
     */
    private Location findPrey()
    {
        Field field = getField();
        Location currentLocation = getLocation();
        List<Location> adjacent = field.adjacentLocations(currentLocation);
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal != null && DIET.contains(animal.getClass())) {
                Organism food = (Organism) animal;
                if(food.isAlive()) {
                    food.setDead();
                    return where;
                }
                return where;
            }
        }
        return null;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Creates actors and populates fields according to a simulation configuration.
 */
public class ActorFactory
{
    private static final Random rand = Randomizer.getRandom();
    private static final List<Class<?>> CREATION_ORDER = List.of(
            Grass.class,
            Deer.class,
            Coyote.class,
            Wolf.class,
            Eagle.class,
            Mouse.class,
            Hunter.class
    );

    private final SimulationConfig config;

    public ActorFactory(SimulationConfig config)
    {
        this.config = config;
    }

    public List<Actor> populate(Field field)
    {
        List<Actor> actors = new ArrayList<>();
        int hunterCount = 0;

        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Location location = new Location(row, col);
                Actor actor = maybeCreateActor(field, location, hunterCount);
                if(actor != null) {
                    actors.add(actor);
                    if(actor instanceof Hunter) {
                        hunterCount++;
                    }
                }
            }
        }

        return actors;
    }

    public List<Actor> createGrassPatches(Field field, Environment environment)
    {
        if(environment.getWeather().getCurrentWeather() != WeatherType.RAINING) {
            return List.of();
        }

        double creationRate = config.getCreationProbability(Grass.class);
        List<Actor> grassActors = new ArrayList<>();
        for(Location location : field.getRandomFreePatches(creationRate)) {
            if(rand.nextDouble() <= creationRate) {
                grassActors.add(new Grass(field, location));
            }
        }

        return grassActors;
    }

    private Actor maybeCreateActor(Field field, Location location, int hunterCount)
    {
        for(Class<?> actorClass : CREATION_ORDER) {
            if(actorClass == Hunter.class && hunterCount >= config.getHunterLimit()) {
                continue;
            }

            if(rand.nextDouble() <= config.getCreationProbability(actorClass)) {
                return createActor(actorClass, field, location);
            }
        }

        return null;
    }

    private Actor createActor(Class<?> actorClass, Field field, Location location)
    {
        if(actorClass == Grass.class) {
            return new Grass(field, location);
        }
        if(actorClass == Hunter.class) {
            return new Hunter(field, location);
        }

        Animal.Gender sex = Randomizer.getRandomSex();
        if(actorClass == Deer.class) {
            return new Deer(true, field, location, sex);
        }
        if(actorClass == Coyote.class) {
            return new Coyote(true, field, location, sex);
        }
        if(actorClass == Wolf.class) {
            return new Wolf(true, field, location, sex);
        }
        if(actorClass == Eagle.class) {
            return new Eagle(true, field, location, sex);
        }
        if(actorClass == Mouse.class) {
            return new Mouse(true, field, location, sex);
        }

        throw new IllegalArgumentException("Unsupported actor type: " + actorClass.getName());
    }
}

import java.util.Random;

/**
 * This class models disease in the simulation. 
 * It stores details about the disease such as 
 * lethality rate, propagation rate and the method of transmission.
 *
 * @version 2022.03.2
*/
public class Disease 
{
    private Random rand = Randomizer.getRandom();
    // The propagation rate of the disease
    private static double PROPAGATION_RATE = 0.0;
    // the lethality rate of the disease
    private static double LETHALITY_RATE = 0.0;
    // the transmission route of the disease 
    private DiseaseType PROPAGATION_MODE;

    /**
     * Creates a new disease with random propagation and lethality rates.
     * double randomValue = rangeMin + (rangeMax - rangeMin) * r.nextDouble();
     * https://stackoverflow.com/questions/3680637/generate-a-random-double-in-a-range
     */
    public Disease() 
    {
        PROPAGATION_RATE = 0.6 * rand.nextDouble(); // max prop. rate is 60%
        LETHALITY_RATE = 0.4 * rand.nextDouble(); // max lethality rate is 40%
        PROPAGATION_MODE = DiseaseType.values()[rand.nextInt(DiseaseType.values().length)];
    }

    /**
     * Create a new disease with given propagation and lethality rates.
     * @param propRate The propagation rate of the disease.
     * @param lethalRate The lethality rate of the disease.
     * @param propMode The propagation mode of the disease. 
     */
    public Disease(double propRate, double lethalRate, DiseaseType propMode)
    {
        PROPAGATION_RATE = propRate;
        LETHALITY_RATE = lethalRate;
        PROPAGATION_MODE = propMode;
    }

    /**
     * Returns the propagation rate of the disease
     */
    public double getPropagationRate() 
    {
        return PROPAGATION_RATE;
    }

    /**
     * Returns the lethality rate of the disease
     */
    public double getLethalityRate() 
    {
        return LETHALITY_RATE;
    }

    /**
     * Returns the disease's mode of transmission
     */
    public DiseaseType getDiseaseType() 
    {
        return PROPAGATION_MODE;
    }
}

