231	     * The list will not include the location itself.
232	     * All locations will lie within the grid.
233	     * @param location The location from which to generate adjacencies.
234	     * @return A list of locations adjacent to that given.
235	     */
236	    public List<Location> adjacentLocations(Location location)
237	    {
238	        assert location != null : "Null location passed to adjacentLocations";
239	        // The list of locations to be returned.
240	        List<Location> locations = new LinkedList<>();
241	        if(location != null) {
242	            int row = location.getRow();
243	            int col = location.getCol();
244	            for(int roffset = -1; roffset <= 1; roffset++) {
245	                int nextRow = row + roffset;
246	                if(nextRow >= 0 && nextRow < depth) {
247	                    for(int coffset = -1; coffset <= 1; coffset++) {
248	                        int nextCol = col + coffset;
249	                        // Exclude invalid locations and the original location.
250	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
251	                            locations.add(new Location(nextRow, nextCol));
