  5	/**
  6	 * Creates actors and populates fields according to a simulation configuration.
  7	 */
  8	public class ActorFactory
  9	{
 10	    private static final List<Class<?>> CREATION_ORDER = List.of(
 11	            Grass.class,
 12	            Deer.class,
 13	            Coyote.class,
 14	            Wolf.class,
 15	            Eagle.class,
 16	            Mouse.class,
 17	            Hunter.class
 18	    );
 19	
 20	    private final SimulationConfig config;
 21	    private final RandomProvider randomProvider;
 22	
 23	    public ActorFactory(RandomProvider randomProvider, SimulationConfig config)
 24	    {
 25	        this.randomProvider = randomProvider;
 26	        this.config = config;
 27	    }
 28	
 29	    public List<Actor> populate(Field field)
 30	    {
 31	        List<Actor> actors = new ArrayList<>();
 32	        int hunterCount = 0;
 33	
 34	        field.clear();
 35	        for(int row = 0; row < field.getDepth(); row++) {
 36	            for(int col = 0; col < field.getWidth(); col++) {
 37	                Location location = new Location(row, col);
 38	                Actor actor = maybeCreateActor(field, location, hunterCount);
 39	                if(actor != null) {
 40	                    actors.add(actor);
 41	                    if(actor instanceof Hunter) {
 42	                        hunterCount++;
 43	                    }
 44	                }
 45	            }
 46	        }
 47	
 48	        return actors;
 49	    }
 50	
 51	    public List<Actor> createGrassPatches(Field field, Environment environment)
 52	    {
 53	        Random rand = randomProvider.getRandom();
 54	        if(environment.getWeather().getCurrentWeather() != WeatherType.RAINING) {
 55	            return List.of();
 56	        }
 57	
 58	        double creationRate = config.getCreationProbability(Grass.class);
 59	        List<Actor> grassActors = new ArrayList<>();
 60	        for(Location location : field.getRandomFreePatches(creationRate)) {
 61	            if(rand.nextDouble() <= creationRate) {
 62	                grassActors.add(new Grass(field, location));
 63	            }
 64	        }
 65	
 66	        return grassActors;
 67	    }
 68	
 69	    private Actor maybeCreateActor(Field field, Location location, int hunterCount)
 70	    {
 71	        Random rand = randomProvider.getRandom();
 72	        for(Class<?> actorClass : CREATION_ORDER) {
 73	            if(actorClass == Hunter.class && hunterCount >= config.getHunterLimit()) {
 74	                continue;
 75	            }
 76	
 77	            if(rand.nextDouble() <= config.getCreationProbability(actorClass)) {
 78	                return createActor(actorClass, field, location);
 79	            }
 80	        }
 81	
 82	        return null;
 83	    }
 84	
 85	    private Actor createActor(Class<?> actorClass, Field field, Location location)
 86	    {
 87	        if(actorClass == Grass.class) {
 88	            return new Grass(field, location);
 89	        }
 90	        if(actorClass == Hunter.class) {
 91	            return new Hunter(field, location);
 92	        }
 93	
 94	        Animal.Gender sex = randomProvider.getRandom().nextBoolean()
 95	                ? Animal.Gender.MALE
 96	                : Animal.Gender.FEMALE;
 97	        if(actorClass == Deer.class) {
 98	            return new Deer(true, field, location, sex);
 99	        }
100	        if(actorClass == Coyote.class) {
101	            return new Coyote(true, field, location, sex);
102	        }
103	        if(actorClass == Wolf.class) {
104	            return new Wolf(true, field, location, sex);
105	        }
106	        if(actorClass == Eagle.class) {
107	            return new Eagle(true, field, location, sex);
108	        }
109	        if(actorClass == Mouse.class) {
110	            return new Mouse(true, field, location, sex);
111	        }
112	
113	        throw new IllegalArgumentException("Unsupported actor type: " + actorClass.getName());
114	    }
115	}

