126	     */
127	    protected Location findFood()
128	    {
129	        Random rand = getRandomProvider().getRandom();
130	        Field field = getField();
131	        List<Location> adjacent = field.adjacentLocations(getLocation());
132	        for(Location loc : adjacent){
133	            if(field.getObjectAt(loc) != null && !(field.getObjectAt(loc) instanceof Hunter)){
134	                Organism organism = (Organism) field.getObjectAt(loc);
135	                if (organism.isDiseased() && organism.getDisease().getDiseaseType() != DiseaseType.CONTACT && organism.getDisease().getPropagationRate() <= rand.nextDouble()){
136	                    // contracts the first contact disease it encounters amongst the adjacent animals
137	                    this.setDisease(organism.getDisease());
138	                    break;
139	                }
140	            }
141	        }
142	        Iterator<Location> it = adjacent.iterator();
143	        // only eats if it's not full (food level less than max)
144	        while(it.hasNext() && foodLevel <= getMaxFoodLevel()) {
145	            Location where = it.next();
146	            Object animal = field.getObjectAt(where);
147	            if(animal != null && getDiet().contains(animal.getClass()))
