47	    static void combinationUtil(Double arr[], Double data[], int start,
48	                                int end, int index, int r)
49	    {
50	        // Current combination is ready to be printed, print it
51	        if (index == r)
52	        {
53	            Double[] res = new Double[r];
54	//            System.out.print("[");
55	            for (int j=0; j<r; j++){
56	//                System.out.print(data[j]+", ");
