61	            }
62	//            System.out.print("]");
63	            System.out.println("");
64	            return;
65	        }
66	        for (int i=start; i<=end && end-i+1 >= r-index; i++)
67	        {
68	            data[index] = arr[i];
69	            combinationUtil(arr, data, i+1, end, index+1, r);
70	        }
71	    }
